import React, { useState } from 'react';
import './Contact.css';

function Contact() {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    message: ''
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log('Form submitted:', formData);
    // Add your form submission logic here
    setFormData({ name: '', email: '', message: '' });
    alert('Thank you for your message! I will get back to you soon.');
  };

  return (
    <section id="contact" className="contact">
      <div className="contact-container">
        <h2>Get In Touch</h2>
        <p className="contact-subtitle">Have a project in mind or just want to chat? Feel free to reach out!</p>
        
        <div className="contact-content">
          <form className="contact-form" onSubmit={handleSubmit}>
            <div className="form-group">
              <input
                type="text"
                name="name"
                placeholder="Your Name"
                value={formData.name}
                onChange={handleChange}
                required
              />
            </div>
            <div className="form-group">
              <input
                type="email"
                name="email"
                placeholder="Your Email"
                value={formData.email}
                onChange={handleChange}
                required
              />
            </div>
            <div className="form-group">
              <textarea
                name="message"
                placeholder="Your Message"
                rows="5"
                value={formData.message}
                onChange={handleChange}
                required
              ></textarea>
            </div>
            <button type="submit" className="submit-btn">Send Message</button>
          </form>

          <div className="contact-info">
            <div className="info-item">
              <h3>📧 Email</h3>
              <p><a href="mailto:villartaariel478@gmail.com">villartaariel478@gmail.com</a></p>
            </div>
            <div className="info-item">
              <h3>📱 Contact Number</h3>
              <p><a href="tel:09672138951">09672138951</a></p>
            </div>
            <div className="info-item">
              <h3>🐙 GitHub</h3>
              <p><a href="https://github.com/M1nDBr34k" target="_blank" rel="noopener noreferrer">github.com/M1nDBr34k</a></p>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

export default Contact;
